{
  "plan": [
    {
      "id": "1",
      "goal": "List all patient documents to verify the complete absence of a 'Pathology' document type.",
      "rationale": "The proof obligation requires listing documents first; confirming no pathology reports exist dictates subsequent steps."
    },
    {
      "id": "2",
      "goal": "Search the entire chart for keywords 'biopsy', 'pathology', 'final diagnosis', and 'specimen'.",
      "rationale": "Required by the proof obligation to ensure no pathology evidence is hidden in progress notes or procedure reports."
    },
    {
      "id": "3",
      "goal": "Review Endoscopy and Procedure-Note documents for embedded biopsy results or histologic descriptions.",
      "rationale": "Biopsy results are sometimes documented within procedure reports when formal pathology reports are missing from the chart shape."
    },
    {
      "id": "4",
      "goal": "Extract documentation of the primary site of origin from imaging (CT/PET) or clinical notes.",
      "rationale": "The specification allows coding primary_site even if histology and behavior cannot be determined due to lack of tissue confirmation."
    },
    {
      "id": "5",
      "goal": "Apply EVIDENCE_INSUFFICIENT for histology and behavior, citing the absence of pathology per proof obligation.",
      "rationale": "Prevents inferring histology from imaging or clinical assertions when tissue diagnosis is not in the record."
    }
  ]
}
